import mlx.core as mx, numpy as np, pathlib, json, sys
L=int(sys.argv[1]); root=pathlib.Path(sys.argv[2] if len(sys.argv)>2 else '/Users/mikuru/qwen38fn-official-pipeline/output/Qwen3.8-Flash-Next-OurAblit-Mixed-MLX-Serve'); M=json.load(open(sys.argv[3] if len(sys.argv)>3 else '/Users/mikuru/qwen-native-runtime/phase0/qwen38fn_manifest.json'))['tensors']; p=f'language_model.model.layers.{L}.'
